using System;using System.IO;using System.Linq;using System.Reflection;using System.Web.Script.Serialization;using System.Security.Cryptography;using System.Collections.Generic;using Microsoft.VisualBasic;using Microsoft.VisualBasic.CompilerServices;
class RuntimeMetadata {
 static object Pin(Assembly a){using(var h=SHA256.Create())return new{name=a.FullName,filename=Path.GetFileName(a.Location),sha256=String.Concat(h.ComputeHash(File.ReadAllBytes(a.Location)).Select(b=>b.ToString("x2"))),bytes=new FileInfo(a.Location).Length};}
 static void Main(string[] args){var tool=Assembly.LoadFrom(args[0]);var read=tool.GetType("MethodBodies38").GetMethod("Read",BindingFlags.NonPublic|BindingFlags.Static);var types=new[]{typeof(ProjectData),typeof(ErrObject),typeof(Information)};var names=new[]{"SetProjectError","ClearProjectError","GetProjectData","CaptureException","Clear","Err"};var rows=new List<object>();foreach(var t in types){rows.Add(new{type=t.FullName,assembly=Pin(t.Assembly),fields=t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance).Select(f=>new{name=f.Name,attributes=f.Attributes.ToString(),thread_static=f.IsDefined(typeof(ThreadStaticAttribute),false)}).ToArray(),methods=t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance).Where(m=>names.Contains(m.Name)).Select(m=>read.Invoke(null,new object[]{m})).ToArray()});}File.WriteAllText(args[1],new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{schema="CURRENT_FRAMEWORK_METADATA_ONLY_NOT_ORIGINAL_EXECUTION",types=rows,original_calls=0}));}
}
